cat > /app/output/login.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <meta name="description" content="Sign in to StreamWave to keep watching unlimited films, series and more." />
  <title>Sign In — StreamWave</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <link rel="stylesheet" href="styles.css" />
</head>
<body class="login-page">
  <header class="site-header login-header" aria-label="Primary navigation">
    <a class="brand" href="index.html" aria-label="StreamWave home">StreamWave</a>
    <label class="select-wrap" aria-label="Select language">
      <span class="select-icon" aria-hidden="true">◎</span>
      <select><option>English</option><option>Español</option><option>Français</option></select>
    </label>
  </header>

  <main class="login-main">
    <section class="login-card" aria-labelledby="login-heading">
      <p class="eyebrow">Welcome back</p>
      <h1 id="login-heading">Enter your info to sign in</h1>
      <p class="login-subtext">Or get started with a new account.</p>
      <form class="auth-form" id="login-form" novalidate>
        <label class="field-label stacked">
          <span>Email address or mobile number</span>
          <input type="text" name="identifier" placeholder="Email address or mobile number" autocomplete="username" required />
        </label>
        <label class="field-label stacked">
          <span>Password</span>
          <input type="password" name="password" placeholder="Password" autocomplete="current-password" minlength="6" required />
        </label>
        <button class="btn btn-large btn-full" type="submit">Continue</button>
        <p class="form-note" id="login-status" role="status" aria-live="polite"></p>
      </form>
      <div class="help-panel">
        <button class="help-toggle" type="button" aria-expanded="false" aria-controls="help-content">Get help <span aria-hidden="true">+</span></button>
        <div id="help-content" class="help-content" hidden>
          <a href="#">Reset your password</a>
          <a href="#">Update email or phone</a>
          <a href="#">Contact Help Centre</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer page-shell login-footer">
    <p>Questions? Contact us.</p>
    <div class="footer-links" aria-label="Footer links">
      <a href="index.html#faq-heading">FAQ</a><a href="#">Help Centre</a><a href="#">Account</a><a href="#">Media Centre</a>
      <a href="#">Privacy</a><a href="#">Terms of Use</a><a href="#">Corporate Information</a><a href="#">Contact Us</a>
    </div>
    <small>This page is protected by Google reCAPTCHA to ensure you're not a bot.</small>
  </footer>

  <script src="script.js"></script>
</body>
</html>
EOF

cat > /app/output/styles.css <<'EOF'
:root {
  color-scheme: dark;
  --bg: #000;
  --panel: #141414;
  --panel-2: #1f1015;
  --text: #fff;
  --muted: #b8b8b8;
  --soft: #777;
  --line: rgba(255,255,255,.14);
  --red: #e50914;
  --red-dark: #b20710;
  --red-glow: rgba(229,9,20,.42);
  --radius: 22px;
  --shell: min(1180px, calc(100% - 40px));
  --shadow: 0 24px 80px rgba(0,0,0,.55);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-width: 320px;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; }
button, input, select { font: inherit; }
button { cursor: pointer; }

.page-shell { width: var(--shell); margin-inline: auto; }
.site-header {
  position: absolute;
  z-index: 20;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: var(--shell);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 24px 0;
}

.brand {
  color: var(--red);
  text-decoration: none;
  font-size: clamp(1.7rem, 4vw, 2.85rem);
  font-weight: 900;
  letter-spacing: -.075em;
  text-transform: uppercase;
  text-shadow: 0 10px 35px rgba(229,9,20,.35);
}

.header-actions { display: flex; align-items: center; gap: 12px; }
.select-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-width: 124px;
  color: var(--text);
}
.select-wrap select {
  width: 100%;
  min-height: 36px;
  appearance: none;
  border: 1px solid rgba(255,255,255,.45);
  border-radius: 999px;
  background: rgba(0,0,0,.58);
  color: var(--text);
  padding: 7px 30px 7px 34px;
  outline: none;
  backdrop-filter: blur(12px);
}
.select-wrap::after {
  content: "⌄";
  position: absolute;
  right: 11px;
  pointer-events: none;
  color: var(--muted);
  top: 7px;
}
.select-icon { position: absolute; left: 12px; z-index: 1; color: var(--muted); font-size: .78rem; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .35em;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(180deg, #ff1b26 0%, var(--red) 55%, var(--red-dark) 100%);
  color: var(--text);
  font-weight: 800;
  text-decoration: none;
  box-shadow: 0 18px 42px var(--red-glow);
  transition: transform .18s ease, box-shadow .18s ease, filter .18s ease;
}
.btn:hover { transform: translateY(-2px); box-shadow: 0 22px 52px rgba(229,9,20,.58); filter: saturate(1.08); }
.btn:active { transform: translateY(0); }
.btn-small { min-height: 36px; padding: 8px 18px; font-size: .9rem; }
.btn-large { min-height: 62px; padding: 14px 30px; font-size: clamp(1.05rem, 2.2vw, 1.45rem); white-space: nowrap; }
.btn-full { width: 100%; }

.hero {
  position: relative;
  min-height: 820px;
  display: flex;
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  border-bottom: 8px solid #232323;
}
.poster-mosaic {
  position: absolute;
  inset: -12% -5% 0;
  background:
    radial-gradient(circle at 50% 20%, rgba(229,9,20,.2), transparent 34%),
    linear-gradient(100deg, rgba(0,0,0,.82), rgba(0,0,0,.2) 46%, rgba(0,0,0,.76)),
    #050505;
  transform: skewY(-3deg);
  filter: saturate(1.1);
}
.tile {
  position: absolute;
  display: grid;
  place-items: end start;
  width: clamp(120px, 15vw, 210px);
  height: clamp(180px, 23vw, 320px);
  padding: 18px;
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(255,255,255,.08), transparent 36%), var(--tile-bg, linear-gradient(#45050a, #090909));
  color: rgba(255,255,255,.8);
  font-weight: 900;
  font-size: clamp(.8rem, 1.2vw, 1.1rem);
  letter-spacing: .08em;
  box-shadow: 0 26px 60px rgba(0,0,0,.72);
  opacity: .74;
}
.t1 { --tile-bg: linear-gradient(145deg,#6c0710,#151515); left: 5%; top: 21%; transform: rotate(-10deg); }
.t2 { --tile-bg: linear-gradient(145deg,#302f3c,#82050e); left: 21%; top: 9%; transform: rotate(7deg); }
.t3 { --tile-bg: linear-gradient(145deg,#86172a,#12070b); left: 37%; top: 28%; transform: rotate(-6deg); }
.t4 { --tile-bg: linear-gradient(145deg,#102b56,#07090f); left: 55%; top: 7%; transform: rotate(9deg); }
.t5 { --tile-bg: linear-gradient(145deg,#8f2bd9,#101010); left: 72%; top: 24%; transform: rotate(-9deg); }
.t6 { --tile-bg: linear-gradient(145deg,#d85b12,#140902); left: 87%; top: 5%; transform: rotate(6deg); }
.t7 { --tile-bg: linear-gradient(145deg,#0b7164,#06100e); left: 67%; top: 58%; transform: rotate(8deg); }
.t8 { --tile-bg: linear-gradient(145deg,#444,#050505); left: 17%; top: 62%; transform: rotate(-8deg); }
.hero-vignette {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    radial-gradient(ellipse at center, transparent 0%, rgba(0,0,0,.32) 40%, #000 84%),
    linear-gradient(180deg, rgba(0,0,0,.82), rgba(0,0,0,.42) 40%, #000 100%);
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 860px;
  padding-top: 108px;
  text-align: center;
}
.eyebrow {
  margin: 0 0 16px;
  color: #ffd7d9;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  font-size: .82rem;
}
h1, h2, h3, p { margin-top: 0; }
.hero h1 {
  margin-bottom: 16px;
  font-size: clamp(3.2rem, 9vw, 6.8rem);
  line-height: .9;
  letter-spacing: -.075em;
  font-weight: 900;
  text-wrap: balance;
}
.hero-price {
  margin-bottom: 28px;
  color: #f2f2f2;
  font-size: clamp(1.18rem, 3vw, 1.75rem);
  font-weight: 700;
}
.hero-price strong { color: #fff; }
.signup-form { max-width: 840px; margin: 0 auto; }
.signup-form > p {
  margin-bottom: 15px;
  color: #f2f2f2;
  font-size: clamp(1rem, 2vw, 1.18rem);
  font-weight: 600;
}
.form-row { display: flex; justify-content: center; gap: 10px; align-items: stretch; }
.field-label {
  position: relative;
  display: block;
  flex: 1 1 420px;
  min-width: 0;
}
.field-label span {
  position: absolute;
  left: 18px;
  top: 8px;
  z-index: 1;
  color: var(--muted);
  font-size: .75rem;
  font-weight: 700;
  opacity: 0;
  transform: translateY(6px);
  transition: .16s ease;
}
.field-label input {
  width: 100%;
  min-height: 62px;
  border: 1px solid rgba(255,255,255,.48);
  border-radius: 999px;
  background: rgba(18,18,18,.78);
  color: #fff;
  padding: 20px 22px;
  font-size: 1.05rem;
  outline: none;
  box-shadow: inset 0 0 0 999px rgba(0,0,0,.08);
  backdrop-filter: blur(12px);
}
.field-label input:focus { border-color: #fff; box-shadow: 0 0 0 4px rgba(229,9,20,.24); }
.field-label input:not(:placeholder-shown) { padding-top: 28px; padding-bottom: 12px; }
.field-label input:not(:placeholder-shown) + span,
.field-label:focus-within span,
.stacked span { opacity: 1; transform: translateY(0); }
.form-note { display: block; min-height: 20px; margin-top: 10px; color: #ffb8bd; font-size: .9rem; }

.content-section { padding: 54px 0; }
.content-section h2,
.cta-panel h2 {
  margin-bottom: 22px;
  font-size: clamp(1.75rem, 4vw, 3.25rem);
  line-height: 1;
  letter-spacing: -.055em;
  font-weight: 900;
}
.section-header { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.carousel-actions { display: flex; gap: 10px; }
.circle-btn {
  width: 46px;
  height: 46px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: #1b1b1b;
  color: #fff;
  font-size: 1.8rem;
  line-height: 1;
  transition: background .18s ease, transform .18s ease;
}
.circle-btn:hover { background: var(--red); transform: scale(1.05); }
.carousel {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: clamp(160px, 19vw, 230px);
  gap: clamp(14px, 2.5vw, 28px);
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scroll-snap-type: inline mandatory;
  scroll-padding-inline: 20px;
  padding: 22px 4px 34px 62px;
  scrollbar-width: thin;
  scrollbar-color: var(--red) #1a1a1a;
}
.poster-card {
  position: relative;
  min-height: clamp(230px, 28vw, 330px);
  display: flex;
  align-items: flex-end;
  padding: 20px;
  scroll-snap-align: start;
  border-radius: 19px;
  overflow: visible;
  isolation: isolate;
  background:
    linear-gradient(180deg, transparent 30%, rgba(0,0,0,.82) 100%),
    radial-gradient(circle at 70% 20%, rgba(255,255,255,.2), transparent 25%),
    var(--poster-bg);
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: var(--shadow);
  transition: transform .22s ease, border-color .22s ease;
}
.poster-card::after {
  content: "";
  position: absolute;
  inset: 10px;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 14px;
